import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
n={'部位管理':'固定一口實際回傳所選槓桿為口數；固定金額／變動金額為金額÷(價格×契約價值)×槓桿，再套最小口數，不向下取整。','固定金額':'固定金額模式每次用此名目金額換可為小數的口數，不是保證金額度或累積損益複利。','交易金額檔案':'跳第一行讀日期／金額CSV，按進場日取金額；以檔名快取，Clear未清快取，缺檔／缺日回0後仍可被最小口數墊高。','金額乘數':'僅變動金額模式把檔案每日金額乘此值再換槓桿口數。','最小口數':'金額模式換出的口數不足即拉到此下限；檔案缺金額也可能仍交易。固定一口不套此下限。','開盤時間':'每日取HHmm起0至5分鐘內最早一根open作開盤；缺這個窗整日排除。','收盤時間':'同樣取起0至5分鐘內最早根open作收盤參考；空當日若跨約則取原開盤合約最後可用open提早回補。','MA濾網天數':'有效日收盤參考的含當日簡單均線，期間至少1；不足期間則多空兩段都不做。','MA上_多槓桿':'前一有效日收盤>=含當日MA時，該日收盤進隔夜多的槓桿／口數倍率，<=0不做。','MA上_空槓桿':'相同前日MA上狀態，次有效日開盤做空倍率，不用次日重新判MA。','MA下_多槓桿':'前有效日收盤<MA時隔夜多倍率。','MA下_空槓桿':'前有效日MA下狀態，次有效日日內空倍率。','開低才空':'使用時次有效日open必須嚴格<前有效日收盤才日內空；隔夜多不受此濾網。','週五收盤':'僅台灣商品，設定跳過且買日週五時不建立隔夜多，不影響次日日內空。','國定假日前日':'台灣商品且買日出現在dictHoliday鍵時跳隔夜多；依載入表，不現算所有國定假日。','美國休日前日':'台灣商品，買日NextDay（週五+3日，其餘+1）命中內建美休算法就跳隔夜多。','美國休日當日':'台灣商品買日命中內建美休算法，跳隔夜多。','美國休日次日':'台灣商品，買日PrevDay（週一−3日，其餘−1）命中美休算法，跳隔夜多。'}
add('夜多日空v3','以均線狀態分配槓桿，前有效日收盤做多到下一有效日開盤，再視開低條件做日內空到收盤。','日夜時段配置',['按曆日取開盤／收盤時刻後5分鐘內最早根open，兩窗都有才成有效日；用有效日收盤含當日MA分上／下狀態。','各相鄰有效日成一組：前日收盤做多、下一日open平；同一前日MA狀態決定次日日內空倍率，可要求次日open嚴格低前收。'],['兩段都在計算時直接建立成對進出紀錄，沒有中途停損／移停；每筆多倉下一有效日open退，空倉當日收盤參考open退。','日內空若開盤和收盤合約不同，改在當日原開盤合約最後一根（不晚於目標收盤）open回補，避免空段跨約。'],[cost,'固定一口其實用槓桿值為可小數口數；金額模式=名目額÷(價×契約價值)×槓桿，不取整，且套最小口數。','假日檢查只取消前日收盤隔夜多，不取消下一日空；僅台灣商品套本地假日表及內建美休算法。'],['下一有效日可能跨過缺窗交易日，不保證相鄰市場交易日；MA也只用有效日收盤。','隔夜多沒有像空段一樣檢查合約一致，可能前收與次開是不同合約，價差未作換倉調整。','固定金額不跟隨策略淨值複利；變動額缺日雖回0，若最小口數>0仍可交易，不能解讀為自動跳過。'],n)
add('你跳我就跳','曆日首根相對前根收盤跳空到門檻，順勢或逆勢建一口子項，固定損可反轉並限制反轉次數。','跳空與反手',['曆日變更先處理舊子項持有到期，再比較本根open−前根close；>=上距離或<=負下距離就新建一口，順勢跟跳空、逆勢反向。','每日可有新子項，不設總口數上限；新子項建立後同根也立即檢查風控。'],['每根只看open，先固定損，未達反轉上限就兩口反向且重設固定／啟移／直停，否則平掉停止；再直接停利，最後移停。','移停只向有利方向更新，當根open達啟移價後從同根open算線，之後open觸線退出；直接停利不需先啟移。','持有日數到期只在下一曆日首根檢查；當日收盤選項回填前根open而非close，隔日開盤用當根open。最後根先close平所有，不再新訊號。','相鄰根session不同在當根風控後按本根open平舊／open+delta重開，並偏移保護線。'],[cost,'每次反轉重設風控但不重設啟動日，持有期限仍從原跳空子項建立日起算。','不使用ValidKBAR或共用交易時刻，每個有效分鐘open都檢查；日計數按曆日，不依商品TradeDate。'],['持有天數0不會在建立同日就平，仍須等下一日界才查；所謂當日收盤也是事後日界回填前根open。','每日新增子項可和前日舊倉重疊，多空子項在同一策略實例FIFO可先互抵；不是各子項獨立投資組合。','直接用跨日兩根價差，若同時跨約可將合約價差當跳空；session換倉發生在訊號／風控之後。'],{'順勢逆勢':'順勢上跳多下跳空；逆勢上跳空下跳多，門檻判含等號。','向上跳空':'前根close的%或點數，本根open−前根close>=距離就觸發，先於向下條件判。','向下跳空':'前根close的%或點數，價差<=負距離才觸發。','停損反轉':'每次初進／反轉價加減Round後距離，open觸固定損就反轉或達限退出。','最多反轉次數':'每子項已反轉<此值才允許再反，達限下一次固定損停止；0初次持倉仍可建立但不能反轉。','持有天數':'啟動日序+此值<=當前日序時，在新曆日首根處理；反轉不重計啟動日，0也要到下次日界才查。','出場時間':'當日收盤回填前根open，隔日開盤當根open；均在下一日界判，不直接在收盤時刻判。','啟動移停比':'每次建倉／反轉價加減距離，後續open達到才開始推線，反轉重設。','移停拉回比':'以當前open換%或點數，線只多上移／空下移；同根更新後也可立即檢查退出。','直接停利比':'每次新倉／反轉價加減距離，固定損之後先查，無需已有移停。'})
add('開高回補沖','開盤高過前N日高價後等待回落，跌到前高下方做空，可停損重進及獲利延後退出。','開高回落與當沖',['先按商品交易日累積日盤high，取得前N日最大；新日open>=前高+X才設等待。新日先跑舊狀態，最後才設定新等待，因此首根不會因新日訊號立刻進。','等待期間HHmm不超最晚進場且KBAR通過，open<=前高−Y時空一口；超時取消。固定損後未滿次數且仍同交易日，可等open<=原進場再空。'],['一般持倉保護僅啟用且KBAR通過、未超最晚停損時，依open先直停、固定損、已有移停，再更新只下移的移停。','到出場時間跨越（本根<=時刻且下根>）時，若選獲利延後且空單價差利潤>=門檻就留倉；否則本根open平。出場早於最晚進場時，同進場交易日整段略過時間退出。','延後中用open不斷下修基準，反彈>=固定延後點數就open退；仍限KBAR及最晚停損。每次出場時刻可再判是否留，選每日重計則重設基準。','換約按共用一口平開後continue；最後根close平。'],[cost,'時間比較先把小於商品開盤HHmm加2400，最晚進場／停損也轉換；但出場時間直接原值，凌晨出場設定不一定能匹配跨越式。','前高只累計商品開始至收盤時窗high，首段要等交易日切換才加歷史，不直接拿既存日K暖機。'],['直停／移停呼叫base退出後未把_stat改無，可能已空手仍維持已進場狀態並阻止新日重新等待；私有_stat也未在Clear重設。','換約未覆寫偏移函式，前高、損線與延後基準不隨delta修正；不能視為跨約價位連續。','延後留倉不代表夜間都有保護，超最晚停損就跳過；時間退出需前後兩根跨過該時刻，缺段或凌晨未正規化會影響。'],{'最晚進場時間':'等待新回落進場的最後HHmm，含等號；小於商品開盤時間會加2400轉為次凌晨。','出場時間':'用本根HHmm<=此值且下根>此值判跨越，以本根open留／平；若早於最晚進場則同進場交易日不查，且此欄未加2400。','前N日高價':'由已完成交易日的日盤high取最近N日最大，樣本不足前高0而不做。','開盤比前高價大X點':'交易日首open>=前N日最高+X才啟等待，固定點數。','比前高價小Y點進場':'等待時取樣open<=前高−Y進空，固定點數。','停損停利':'使用才跑一般空倉直停／固定損／移停；延後模式自身的拉回退出仍可獨立檢查。','最晚停損時間':'一般風控、延後移停及停損重進時限，HHmm小於商品開盤加2400；超時不查。','最多進場次數':'實作計已停損次數，只有停損後計數<此值且同原進場交易日才排重進；初次不受0禁止。','停損比':'每次空進場價加%或點數作固定損，僅open>=才退並計一次停損。','啟動移停比':'每次進場價減%或點數，open<=此價才更新一般空移停。','移停拉回比':'以目前open加%或點數成空移停線，只准下移，open>=可退出。','直接停利比':'空進場價減距離，風控第一順位open<=就平，不需已啟移。','延後出場':'獲利延後在跨出場時間時需價差利潤>=門檻，否則原時刻open平；不是固定延長一天。','獲利以上延後':'空單進場價−目前open的固定點數門檻，含等號，未扣滑價判。','延後移動停利':'延後狀態的最低取樣open加固定點數，open反彈>=即退；與一般移停比的%格式不同。','移停每日重計':'每次跨出場時刻仍符合延後時，重設延後低基準為目前open；不選則保留原低點。','KBAR間隔ex':'等待回落、一般風控、停損重進及延後移停都依相位；每日設定等待、時間退出與末筆不受限。','開始交易時間':'ValidKBAR相位原點，不是策略日首open或等新訊號的硬起時。'})
